insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('DZ', 'DZ-P-19', 'Achat 19 % déductible', '{}'::jsonb, 'Achats de biens et services au taux normal, déductibles', 'percent', 19, 'purchase', 'domestic', date '2017-01-01', null, 'Code des taxes sur le chiffre d''affaires — la taxe ayant grevé les biens et services acquis pour les besoins de l''exploitation et non exclus du droit à déduction (art. 41) est déductible de la taxe due par l''assujetti ; art. 21 pour le taux', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('DZ', 'DZ-P-19-IMMO', 'Achat d''immobilisations 19 % déductible', '{}'::jsonb, 'Acquisitions d''immobilisations au taux normal, déductibles', 'percent', 19, 'purchase', 'domestic', date '2017-01-01', null, 'Code des taxes sur le chiffre d''affaires — la taxe ayant grevé les biens constituant des immobilisations est déductible dans les mêmes conditions que celle grevant les biens et services, sous réserve des exclusions de l''art. 41 ; art. 21 pour le taux', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('DZ', 'DZ-P-19-ND', 'Achat 19 % non déductible (art. 41)', '{}'::jsonb, 'Biens et services exclus du droit à déduction : notamment les véhicules de tourisme ne constituant pas l''outil indispensable de l''activité, et les biens ou services non liés à l''exploitation', 'percent', 19, 'purchase', 'domestic', date '2017-01-01', null, 'Code des taxes sur le chiffre d''affaires, art. 41 — exclusions du droit à déduction, notamment les véhicules de tourisme qui ne constituent pas l''outil indispensable à l''exercice de l''activité ; la taxe non déductible est un élément du coût du bien ou du service acquis', 'S', null, 140, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('DZ', 'DZ-P-9', 'Achat 9 % déductible', '{}'::jsonb, 'Achats de biens et services relevant du taux réduit de l''article 23, déductibles', 'percent', 9, 'purchase', 'domestic', date '2017-01-01', null, 'Code des taxes sur le chiffre d''affaires, art. 23 pour le taux ; la taxe est déductible dans les mêmes conditions que celle du taux normal', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('DZ', 'DZ-P-IMP-19', 'Importation 19 % (TVA acquittée en douane)', '{}'::jsonb, 'TVA liquidée et perçue par les services des douanes lors du dédouanement', 'percent', 19, 'purchase', 'import', date '2017-01-01', null, 'Code des taxes sur le chiffre d''affaires — la taxe sur la valeur ajoutée à l''importation est liquidée et perçue par les services des douanes sur une base incluant la valeur en douane et les droits et taxes d''entrée, à l''exclusion de la taxe elle-même ; le document douanier justifie la déduction. Le numéro d''article exact de l''assiette à l''importation, dans la numérotation en vigueur, n''a pas pu être vérifié dans une édition consolidée officielle cette session : à faire relire', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('DZ', 'DZ-S-19', 'Vente 19 %', '{}'::jsonb, 'Livraisons de biens et prestations de services au taux normal', 'percent', 19, 'sale', 'domestic', date '2017-01-01', null, 'Code des taxes sur le chiffre d''affaires, art. 21 — « la taxe sur la valeur ajoutée est perçue au taux normal de 19 % », taux résiduel applicable à toute opération taxable qui ne relève ni du taux réduit de l''art. 23 ni d''une exonération ; art. 14 — pour une vente de biens, le fait générateur est constitué par la livraison juridique ou matérielle du bien', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('DZ', 'DZ-S-19-SRV', 'Prestation de services 19 % — TVA sur les encaissements', '{}'::jsonb, 'Prestations de services au taux normal : le fait générateur est l''encaissement, total ou partiel, du prix', 'percent', 19, 'sale', 'domestic', date '2017-01-01', null, 'Code des taxes sur le chiffre d''affaires, art. 14 — « pour les prestations de services, le fait générateur est constitué par l''encaissement partiel ou total du prix » ; à défaut d''encaissement, la taxe devient exigible à l''expiration d''un délai d''un an à compter de la livraison juridique ou matérielle, régularisation que ce pack ne modélise pas ; art. 21 pour le taux', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, true, '44572', 'ctca', null, null, null, null),
  ('DZ', 'DZ-S-9', 'Vente 9 %', '{}'::jsonb, 'Produits, biens, travaux, opérations et services énumérés à l''article 23 du CTCA (produits alimentaires de base, produits pharmaceutiques, livres, transport ferroviaire de voyageurs, actes médicaux, notamment)', 'percent', 9, 'sale', 'domestic', date '2017-01-01', null, 'Code des taxes sur le chiffre d''affaires, art. 23 — « le taux réduit de la taxe sur la valeur ajoutée est fixé à 9 %. Il s''applique aux produits, biens, travaux, opérations et services ci-après : ... » ; un bien ou un service qui n''y figure pas relève du taux normal de l''art. 21', 'S', null, 30, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('DZ', 'DZ-S-EXO', 'Opération exonérée (art. 8 à 12)', '{}'::jsonb, 'Opérations exonérées énumérées aux articles 8 à 12 du CTCA (notamment les produits et services de première nécessité, les opérations bancaires réservées aux établissements financiers, les biens acquis dans le cadre d''un régime privilégié)', 'percent', 0, 'sale', 'exempt', date '2017-01-01', null, 'Code des taxes sur le chiffre d''affaires, art. 8, 9, 10, 11 et 12 — opérations exonérées de la taxe sur la valeur ajoutée. Le pack ne reprend pas la liste, longue et modifiée à chaque loi de finances ; le code exact de l''exonération applicable à une opération donnée se lit dans l''article visé sur la facture', 'E', null, 50, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('DZ', 'DZ-S-EXP', 'Exportation exonérée', '{}'::jsonb, 'Vente de marchandises exportées, exonérée avec maintien du droit à déduction', 'percent', 0, 'sale', 'export', date '2017-01-01', null, 'Code des taxes sur le chiffre d''affaires, art. 13, section I — « les affaires de vente et de façon qui portent sur les marchandises exportées » sont exonérées, sous réserve de la justification de l''exportation par les documents douaniers ; section III — les antiquités, œuvres d''art et métaux précieux restent exclus de l''exonération ; l''exportation ouvre droit à déduction de la taxe ayant grevé les éléments du prix de l''opération exonérée', 'G', null, 40, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'ctca', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

