insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('DZ', 'DZ-G50', 'Déclaration mensuelle — série G n° 50', array['month']::declaration_period[], 'month'::declaration_period, date '2017-01-01', null, 'Code des taxes sur le chiffre d''affaires, art. 28 — les redevables souscrivent, avant le vingtième jour de chaque mois, une déclaration mensuelle des opérations réalisées au titre du mois précédent, y compris en l''absence d''opérations taxables (« déclaration Néant ») ; art. 76-1 — paiement mensuel de la taxe sur le chiffre d''affaires réalisé, au titre du mois précédent, par les contribuables soumis au régime du réel, entre le 1er et le 20 du mois. Le modèle officiel de l''imprimé série G n° 50 n''a pas été retrouvé publié en texte consolidé cette session : les cases de ce formulaire suivent le contenu que l''article 28 impose (opérations taxables et exonérées, taxe exigible, déductions), et non la numérotation de l''imprimé lui-même.', true,'day_of_month_after_period'::filing_deadline_rule, 20, null, 'Code des taxes sur le chiffre d''affaires, art. 76-1, tel que retranscrit par le calendrier fiscal de la Direction générale des impôts : dépôt et paiement entre le 1er et le 20 du mois qui suit celui des opérations, reporté au premier jour ouvrable suivant lorsque le 20 tombe un jour férié ou chômé', 'mfdgi-calendrier', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

