  ('DZ', 'DZ-G50', 'CAT', 'total', 'Chiffre d''affaires total du mois', '{}'::jsonb, 50, null, array['CA19', 'CA9', 'EXP', 'EXO']::text[], '{}'::text[], null, null, false, false, null, 'Code des taxes sur le chiffre d''affaires, art. 28 — montant des opérations taxables et exonérées', 'ctca'),
