update country_defaults set
  numbering_gapless             = true,
  number_format                 = '{CODE}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Décret exécutif n° 05-468 du 10 décembre 2005 ; décret exécutif n° 16-66 du 16 février 2016, art. 5, qui reprend la même règle pour les documents équivalents des secteurs agricole, de la pêche et de l''artisanat — les factures et documents en tenant lieu sont extraits d''un carnet à souches, ou d''une suite logicielle, à « numération de série ininterrompue et chronologique ». Le texte impose la continuité de la séquence, jamais une remise à zéro annuelle ni une forme particulière du numéro.',
  numbering_source_key          = 'decret-05-468',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = 'Code des taxes sur le chiffre d''affaires, art. 14 — pour une vente, le fait générateur est la livraison juridique ou matérielle du bien ; pour une prestation de services, il est constitué par l''encaissement partiel ou total du prix, avec exigibilité au plus tard un an après la livraison à défaut d''encaissement — régularisation que ce pack ne modélise pas. delivery_date dit le principe des ventes de biens ; la branche des prestations de services est portée par les taxes de service en cash_basis, et non par une seconde règle du pays.',
  tax_point_source_key          = 'ctca',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'À la date de ce pack, aucun texte de portée générale n''oblige les entreprises algériennes à échanger des factures électroniques entre elles : le Code des taxes sur le chiffre d''affaires et le décret exécutif n° 05-468 du 10 décembre 2005 organisent la facture sur support ordinaire, et la Direction générale des impôts déploie des téléservices de déclaration et de paiement (Jibaya''tic) sans qu''un format ni une obligation de facturation électronique interentreprises n''aient été publiés et vérifiés cette session. Une facturation numérique existe déjà pour certains grands comptes et fournisseurs de l''État, sous des dispositifs particuliers que ce pack ne modélise pas faute de texte consolidé retrouvé.',
  einvoice_source_key           = 'mfdgi-tva',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'DZ';
